inputs.shell_command:
set -euo pipefail
cd /home/hesham/gova
branch=$(git branch --show-current)
[ "$branch" = main ] || { echo "canonical workspace is not on main: $branch"; exit 42; }
tracked=$(git status --porcelain --untracked-files=no)
[ -z "$tracked" ] || { echo "canonical tracked workspace is dirty; refusing sync"; printf '%s\n' "$tracked"; exit 42; }
git fetch --prune origin main
git pull --ff-only origin main
[ "$(git rev-parse HEAD)" = "$(git rev-parse origin/main)" ] || { echo "canonical sync mismatch"; exit 43; }
echo "canonical synced=$(git rev-parse HEAD)"
